#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE=".env.launch-cutover"

ask_required() {
  local key="$1" prompt="$2" value
  ask "$key" "$prompt"
  value="${!key}"
  if [[ -z "${value//[[:space:]]/}" ]]; then
    warn "$key is required; no cutover gate accepts empty evidence."
    exit 2
  fi
}

load_existing_required() {
  local key="$1" value
  value=$(_existing "$key" || true)
  if [[ -z "${value//[[:space:]]/}" ]]; then
    warn "$key is missing from $ENV_FILE; observation closure cannot continue."
    exit 2
  fi
  printf -v "$key" '%s' "$value"
}

validate_utc_timestamp() {
  local key="$1" value="${!1}"
  if [[ ! "$value" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ ]]; then
    warn "$key must be UTC ISO-8601 in YYYY-MM-DDTHH:MM:SSZ form."
    exit 2
  fi
}

close_observation() {
  local key
  if [[ ! -f "$ENV_FILE" ]]; then
    warn "$ENV_FILE does not exist; complete the cutover start before closing observation."
    exit 2
  fi
  for key in DOKPLOY_DASHBOARD_URL CUTOVER_REHEARSAL_ID CUTOVER_APPROVAL_ID ROLLBACK_OWNER TARGET_API_SERVICE TARGET_DATABASE_SERVICE TARGET_DATABASE_NAME TARGET_RABBITMQ_VHOST TARGET_MEDIA_BUCKET LEGACY_INVENTORY_ID PRE_CUTOVER_BACKUP_EVIDENCE_ID RESTORE_EVIDENCE_ID QUIESCE_EVIDENCE_ID QUIET_POINT_LEGACY_BACKUP_EVIDENCE_ID PAYMENT_EVIDENCE_ID TARGET_DATABASE_CONFIRMATION IMAGE_DIGEST MIGRATION_EVIDENCE_ID CLEAN_PRODUCTION_BASELINE_BACKUP_ID SMTP_EVIDENCE_ID SMTP_MODE_DECISION SMTP_UNRESTRICTED_APPROVAL_ID SMTP_UNRESTRICTED_EVIDENCE_ID TRAFFIC_ROLLBACK_CONTROL TRAFFIC_SWITCHED_AT_UTC TRAFFIC_SWITCH_EVIDENCE_ID SMOKE_EVIDENCE_ID OBSERVATION_STARTED_AT_UTC; do
    load_existing_required "$key"
  done
  if [[ "$SMTP_MODE_DECISION" != "UNRESTRICTED" ]]; then
    warn "Public launch cannot close unless the recorded SMTP mode is UNRESTRICTED."
    exit 2
  fi
  if [[ "$TARGET_DATABASE_CONFIRMATION" != "$TARGET_DATABASE_SERVICE/$TARGET_DATABASE_NAME" ]]; then
    warn "Recorded database confirmation does not match the target service/database pair."
    exit 2
  fi
  if [[ ! "$IMAGE_DIGEST" =~ ^sha256:[0-9a-fA-F]{64}$ ]]; then
    warn "Recorded image digest is not an immutable sha256 digest."
    exit 2
  fi
  validate_utc_timestamp TRAFFIC_SWITCHED_AT_UTC
  validate_utc_timestamp OBSERVATION_STARTED_AT_UTC

  TOTAL_STAGES=1
  banner "Koala production observation closure"
  stage "Observation closure"
  say "This path reads the prior evidence and never replays reset, deploy, SMTP or traffic steps."
  say "Verified target: $TARGET_API_SERVICE -> $TARGET_DATABASE_SERVICE/$TARGET_DATABASE_NAME"
  say "State target: RabbitMQ $TARGET_RABBITMQ_VHOST / media $TARGET_MEDIA_BUCKET"
  say "Image: $IMAGE_DIGEST"
  say "Rollback role/control: $ROLLBACK_OWNER / $TRAFFIC_ROLLBACK_CONTROL"
  say "Observation started: $OBSERVATION_STARTED_AT_UTC"
  confirm "Has the 24-hour observation window completed without unresolved launch alarms?" || exit 2
  ask_required OBSERVATION_COMPLETED_AT_UTC "24-hour observation completion (UTC ISO-8601):"
  validate_utc_timestamp OBSERVATION_COMPLETED_AT_UTC
  ask_required OBSERVATION_EVIDENCE_ID "24-hour alarm/dashboard evidence ID or URL:"
  ask_required OBSERVATION_DURATION_EVIDENCE_ID "Immutable evidence that start-to-finish is at least 24 hours:"
  confirm "Does that immutable record prove at least 24 hours elapsed after OBSERVATION_STARTED_AT_UTC?" || exit 2
  ask_required ROLLBACK_DECISION "Final decision (PROCEED or ROLLBACK):"
  if [[ "$ROLLBACK_DECISION" != "PROCEED" && "$ROLLBACK_DECISION" != "ROLLBACK" ]]; then
    warn "ROLLBACK_DECISION must be exactly PROCEED or ROLLBACK."
    exit 2
  fi
  write_env OBSERVATION_COMPLETED_AT_UTC "$OBSERVATION_COMPLETED_AT_UTC"
  write_env OBSERVATION_EVIDENCE_ID "$OBSERVATION_EVIDENCE_ID"
  write_env OBSERVATION_DURATION_EVIDENCE_ID "$OBSERVATION_DURATION_EVIDENCE_ID"
  write_env ROLLBACK_DECISION "$ROLLBACK_DECISION"
  if [[ "$ROLLBACK_DECISION" == "ROLLBACK" ]]; then
    warn "Stop traffic, preserve the current production database and follow the pre-approved rollback path."
    exit 2
  fi
  say "The 24-hour observation is closed; retire legacy resources only under a separate approved change."
  finish
}

MODE="${1:-cutover}"
if [[ "$MODE" == "--close-observation" ]]; then
  close_observation
  exit 0
fi
if [[ "$MODE" != "cutover" ]]; then
  warn "Unknown mode. Use no argument for cutover, or --close-observation after the 24-hour window."
  exit 2
fi

banner "Koala production launch cutover"

stage "Scope and approval"
say "Open docs/runbooks/launch-cutover.md and keep the change record beside it."
ask_required CUTOVER_REHEARSAL_ID "Final rehearsal evidence ID or URL:"
confirm "Has prerequisite step 9 and the final acceptance rehearsal completed?" || exit 2
ask_required DOKPLOY_DASHBOARD_URL "Dokploy dashboard URL (never paste credentials):"
if [[ "$DOKPLOY_DASHBOARD_URL" != http://* && "$DOKPLOY_DASHBOARD_URL" != https://* || "$DOKPLOY_DASHBOARD_URL" == *"@"* ]]; then
  warn "DOKPLOY_DASHBOARD_URL must be an HTTP(S) URL without embedded credentials."
  exit 2
fi
open_url "$DOKPLOY_DASHBOARD_URL"
ask_required CUTOVER_APPROVAL_ID "Approved cutover record ID or URL:"
ask_required ROLLBACK_OWNER "Non-personal rollback owner role/on-call alias:"
confirm "Do two approvers accept the scope, 24-hour observation window and rollback plan?" || exit 1
write_env DOKPLOY_DASHBOARD_URL "$DOKPLOY_DASHBOARD_URL"
write_env CUTOVER_REHEARSAL_ID "$CUTOVER_REHEARSAL_ID"
write_env CUTOVER_APPROVAL_ID "$CUTOVER_APPROVAL_ID"
write_env ROLLBACK_OWNER "$ROLLBACK_OWNER"

stage "Target and legacy inventory"
step "Copy only immutable aliases or resource IDs; never copy a password or connection string."
ask_required TARGET_API_SERVICE "Target production API service alias:"
ask_required TARGET_DATABASE_SERVICE "Target production PostgreSQL service alias:"
ask_required TARGET_DATABASE_NAME "Target empty database name:"
ask_required TARGET_RABBITMQ_VHOST "Target production RabbitMQ vhost alias:"
ask_required TARGET_MEDIA_BUCKET "Target production media bucket/prefix alias:"
ask_required LEGACY_INVENTORY_ID "Legacy resource inventory evidence ID or URL:"
confirm "Are target and legacy resources separate, and are unrelated resources marked out of scope?" || exit 1
write_env TARGET_API_SERVICE "$TARGET_API_SERVICE"
write_env TARGET_DATABASE_SERVICE "$TARGET_DATABASE_SERVICE"
write_env TARGET_DATABASE_NAME "$TARGET_DATABASE_NAME"
write_env TARGET_RABBITMQ_VHOST "$TARGET_RABBITMQ_VHOST"
write_env TARGET_MEDIA_BUCKET "$TARGET_MEDIA_BUCKET"
write_env LEGACY_INVENTORY_ID "$LEGACY_INVENTORY_ID"

stage "Immutable backup"
step "Verify logical dump, physical base, WAL, checksums, Object Lock, versioning and replication."
step "Run ops/backup/postgres-backup.sh --dry-run before the approved final backup."
ask_required PRE_CUTOVER_BACKUP_EVIDENCE_ID "Pre-cutover backup evidence ID or URL:"
confirm "Is the checksum valid, RPO within 15 minutes and latest daily backup under 26 hours old?" || exit 1
write_env PRE_CUTOVER_BACKUP_EVIDENCE_ID "$PRE_CUTOVER_BACKUP_EVIDENCE_ID"

stage "Isolated restore drill"
step "Create a disposable empty recovery database through the approved platform workflow."
step "Run restore-latest.sh --dry-run, verify the target, then use its explicit empty-target confirmation."
step "Validate Liquibase, anonymous row counts, foreign keys and a read-only smoke; record RPO and RTO."
ask_required RESTORE_EVIDENCE_ID "Restore drill evidence ID or URL:"
confirm "Did the isolated restore pass without recording secrets or personal rows?" || exit 1
write_env RESTORE_EVIDENCE_ID "$RESTORE_EVIDENCE_ID"

stage "Quiesce writes and queues"
step "Enable maintenance and stop the legacy application service completely so every producer, consumer and scheduler is silent."
step "Record email, SMS, push, profile-sync and email DLQ counts; do not purge or replay them."
step "Record settlement_tasks, iys_consent_tasks and account_media_deletion_outbox counts separately; they are database work queues."
step "Wait for active payment/refund operations to finish, then take the final quiet-point backup."
ask_required QUIESCE_EVIDENCE_ID "Quiet-point evidence ID or URL:"
ask_required QUIET_POINT_LEGACY_BACKUP_EVIDENCE_ID "Legacy quiet-point backup ID/checksum evidence:"
confirm "Are writes stopped, financial operations settled and legacy resources preserved for rollback?" || exit 1
write_env QUIESCE_EVIDENCE_ID "$QUIESCE_EVIDENCE_ID"
write_env QUIET_POINT_LEGACY_BACKUP_EVIDENCE_ID "$QUIET_POINT_LEGACY_BACKUP_EVIDENCE_ID"

stage "iyzico live configuration gate"
step "Have the payment owner verify the live merchant, marketplace feature, rates, SFTP and callbacks."
step "Set live credentials only in production secret storage; never paste them here."
step "Set SERVICE_ENVIRONMENT=production and IYZICO_BASE_URL=https://api.iyzipay.com together before the first production startup."
ask_required PAYMENT_EVIDENCE_ID "Payment environment approval evidence ID or URL:"
confirm "Are the live environment guard inputs approved and ready for the first production startup, with no Sandbox credential or URL?" || exit 1
write_env PAYMENT_EVIDENCE_ID "$PAYMENT_EVIDENCE_ID"

stage "Clean database and deploy"
warn "The platform reset is destructive. This wizard will not execute it."
say "Target requiring typed confirmation: $TARGET_DATABASE_SERVICE/$TARGET_DATABASE_NAME"
ask_required TARGET_DATABASE_CONFIRMATION "Type the exact service/database pair shown above:"
if [[ "$TARGET_DATABASE_CONFIRMATION" != "$TARGET_DATABASE_SERVICE/$TARGET_DATABASE_NAME" ]]; then
  warn "Typed target does not match the approved service/database pair."
  exit 2
fi
confirm "Do both approvers confirm this exact target is the empty production database?" || exit 1
step "Use the platform's approved reset/create control, then deploy the verified v* image digest."
ask_required IMAGE_DIGEST "Deployed image digest (sha256: followed by 64 hex characters):"
if [[ ! "$IMAGE_DIGEST" =~ ^sha256:[0-9a-fA-F]{64}$ ]]; then
  warn "IMAGE_DIGEST must be an immutable sha256 digest."
  exit 2
fi
ask_required MIGRATION_EVIDENCE_ID "Liquibase, zero-data and no-seed evidence ID or URL:"
confirm "Are QA variables absent, business tables empty, and a second startup still seed-free?" || exit 1
step "Take a clean production baseline backup before any public traffic."
ask_required CLEAN_PRODUCTION_BASELINE_BACKUP_ID "Clean production baseline backup ID/checksum evidence:"
write_env TARGET_DATABASE_CONFIRMATION "$TARGET_DATABASE_CONFIRMATION"
write_env IMAGE_DIGEST "$IMAGE_DIGEST"
write_env MIGRATION_EVIDENCE_ID "$MIGRATION_EVIDENCE_ID"
write_env CLEAN_PRODUCTION_BASELINE_BACKUP_ID "$CLEAN_PRODUCTION_BASELINE_BACKUP_ID"

stage "SMTP recipient gate"
step "Start with MAIL_DELIVERY_MODE=ALLOWLIST and controlled launch recipients only."
step "Verify MAIL_ALLOWED_RECIPIENTS is non-empty, one allowed delivery, one suppressed recipient and an empty DLQ."
ask_required SMTP_EVIDENCE_ID "SMTP allowlist evidence ID or URL:"
ask_required SMTP_MODE_DECISION "SMTP mode decision (KEEP_ALLOWLIST or UNRESTRICTED):"
if [[ "$SMTP_MODE_DECISION" == "KEEP_ALLOWLIST" ]]; then
  write_env SMTP_EVIDENCE_ID "$SMTP_EVIDENCE_ID"
  write_env SMTP_MODE_DECISION "$SMTP_MODE_DECISION"
  warn "ALLOWLIST is preserved safely; public launch is on HOLD and traffic must remain closed."
  exit 3
fi
if [[ "$SMTP_MODE_DECISION" != "UNRESTRICTED" ]]; then
  warn "SMTP_MODE_DECISION must be exactly KEEP_ALLOWLIST or UNRESTRICTED."
  exit 2
fi
confirm "Does a separate approved change authorize UNRESTRICTED delivery now?" || exit 1
ask_required SMTP_UNRESTRICTED_APPROVAL_ID "UNRESTRICTED delivery approval record ID or URL:"
step "Set MAIL_DELIVERY_MODE=UNRESTRICTED in production secret storage and restart the app."
step "Send to one controlled real recipient and verify delivery; public traffic stays closed until it passes."
ask_required SMTP_UNRESTRICTED_EVIDENCE_ID "UNRESTRICTED delivery evidence ID or URL:"
confirm "Is production now running UNRESTRICTED and did the controlled delivery pass?" || exit 1
write_env SMTP_EVIDENCE_ID "$SMTP_EVIDENCE_ID"
write_env SMTP_MODE_DECISION "$SMTP_MODE_DECISION"
write_env SMTP_UNRESTRICTED_APPROVAL_ID "$SMTP_UNRESTRICTED_APPROVAL_ID"
write_env SMTP_UNRESTRICTED_EVIDENCE_ID "$SMTP_UNRESTRICTED_EVIDENCE_ID"

stage "Smoke and observation start"
ask_required TRAFFIC_ROLLBACK_CONTROL "Approved maintenance/ingress/DNS rollback control:"
say "Open public traffic only to the verified target service: $TARGET_API_SERVICE"
confirm "Are SMTP UNRESTRICTED, iyzico Live and the clean production baseline all verified?" || exit 2
step "Switch maintenance/ingress/DNS through the approved platform control."
ask_required TRAFFIC_SWITCHED_AT_UTC "Traffic switch time (UTC ISO-8601):"
validate_utc_timestamp TRAFFIC_SWITCHED_AT_UTC
ask_required TRAFFIC_SWITCH_EVIDENCE_ID "Traffic switch evidence ID or URL:"
write_env TRAFFIC_ROLLBACK_CONTROL "$TRAFFIC_ROLLBACK_CONTROL"
write_env TRAFFIC_SWITCHED_AT_UTC "$TRAFFIC_SWITCHED_AT_UTC"
write_env TRAFFIC_SWITCH_EVIDENCE_ID "$TRAFFIC_SWITCH_EVIDENCE_ID"
step "Run only health, readiness, session, harmless read and authorization checks."
step "Keep live payment+refund outside deploy smoke; it requires its own human-approved record."
ask_required SMOKE_EVIDENCE_ID "Narrow production smoke evidence ID or URL:"
confirm "Did the narrow production smoke pass?" || exit 2
write_env SMOKE_EVIDENCE_ID "$SMOKE_EVIDENCE_ID"
ask_required OBSERVATION_STARTED_AT_UTC "24-hour observation start (UTC ISO-8601):"
validate_utc_timestamp OBSERVATION_STARTED_AT_UTC
write_env OBSERVATION_STARTED_AT_UTC "$OBSERVATION_STARTED_AT_UTC"
warn "Observation is now running. Do not re-run cutover stages."
say "After at least 24 hours, run: ENV_FILE=$ENV_FILE ops/launch/launch-cutover-wizard.sh --close-observation"
exit 3
